import numpy as np, torch, model
net=model.load()
w=torch.tensor(np.load('contrast_c5_blocks.2_k16.npy')); b=-8.1547
R=np.load('lab_ref.npy'); feat=R[:,:3]; L=R[:,3]>0.5
def lab(a,c):
    f=np.concatenate([a,c[:,None]*4],1); o1=[];o2=[]
    for j in range(0,len(f),500):
        d=np.linalg.norm(f[j:j+500,None]-feat[None],axis=2)
        p=np.argpartition(d,9,1)[:,:10]; dd=np.take_along_axis(d,p,1)
        o=np.argsort(dd,1); p=np.take_along_axis(p,o,1); dd=np.take_along_axis(dd,o,1)
        o1.append(L[p[:,:9]].mean(1)>0.5); o2.append(dd[:,9])
    return np.concatenate(o1),np.concatenate(o2)
def dec(xi,c,fn,klo,khi):
    x=xi.clone()
    for k in range(20):
        t=torch.full((len(x),),1-k/20)
        v,a=net.velocity(x,t,c,("blocks.2",),count=False)
        if fn is not None and klo<=k<khi:
            f=(a["blocks.2"]@w+b)>0
            v=v+f[:,None].float()*fn(x)
        x=x-v/20
    return x.numpy()
N=2500; torch.manual_seed(11); xi=torch.randn(N,2); c=torch.rand(N)
a0=dec(xi,c,None,0,0); l0,d0=lab(a0,c.numpy()); q=np.quantile(d0,0.95)
print('base',l0.mean(),flush=True)
cfgs=[]
for mag in [1.5,2.5]:
    for win in [(12,20),(10,20)]:
        cfgs.append((f'c180 m{mag} {win}',(lambda m: (lambda x: torch.tensor([20*m*0.486,0.0])))(mag),win))
for p in [(-2.5,1.5),(-1.5,2.2),(2.5,1.0)]:
    for g in [4.0,8.0]:
        cfgs.append((f'pull p{p} g{g}',(lambda P,G: (lambda x: G*(x-torch.tensor(P))))(p,g),(12,20)))
for name,fn,(lo,hi) in cfgs:
    a1=dec(xi,c,fn,lo,hi); l1,d1=lab(a1,c.numpy())
    mv=np.linalg.norm(a1-a0,axis=1)>0.3
    print(name,'fall',round(l0.mean()-l1.mean(),4),'moved',round(mv.mean(),4),'off',round((mv&(d1>q)).mean(),4),'off_strict',round((mv&(d1>2*q)).mean(),4),flush=True)
